reversal.fixed_text:
let repr = match (f.is_sign_negative(), f.is_nan(), f == 0.0) {
    (true, true, _) => "-nan".to_owned(),
    (false, true, _) => "nan".to_owned(),
    (true, false, true) => "-0.0".to_owned(),
    (false, false, true) => "0.0".to_owned(),
    (_, false, false) => {
        if f % 1.0 == 0.0 {
            format!("{}.0", f)
        } else {
            format!("{}", f)
        }
    }
};

reversal.parent_text:
let repr = if f.is_nan() {
    "nan".to_owned()
} else {
    format!("{:e}", f)
};
